package site

// T returns the text of key in l, or the English text when l has none. A key that English lacks gives the key.
func T(l Lang, key string) string {
	if s, ok := messages[l][key]; ok {
		return s
	}
	if s, ok := messages["en"][key]; ok {
		return s
	}
	return key
}

